def find_topmost_carpet(n, carpets, point):
    # Initialize a dictionary to store the carpet information
    carpet_dict = {}
    for i in range(n):
        # Get the current carpet's information
        a, b, g, k = carpets[i]
        # Check if the current carpet covers the point
        if a <= point[0] < a + g and b <= point[1] < b + k:
            # If it does, add it to the dictionary with its index as the key
            carpet_dict[i] = (a, b, g, k)

    # If the dictionary is empty, return -1
    if not carpet_dict:
        return -1

    # Otherwise, return the index of the topmost carpet
    return max(carpet_dict, key=carpet_dict.get)
