def cantor_numbering(N: int) -> str:
    if N < 1:
        raise ValueError("N must be a positive integer")

    numerator = 1
    denominator = 1

    while N > 1:
        if N % 3 == 1:
            numerator *= 2
            N -= 1
        elif N % 3 == 2:
            denominator *= 2
            N -= 2
        else:
            numerator *= 2
            denominator *= 2
            N -= 3

    return f"{numerator}/{denominator}"
