def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 1:
        raise ValueError("n and m must be positive integers")
    if n == 1:
        return 1
    if m == 1:
        return n
    if m == 2:
        return n * (n - 1) // 2
    dp = [0] * (m + 1)
    dp[0] = 1
    dp[1] = n
    dp[2] = n * (n - 1) // 2
    for i in range(3, m + 1):
        dp[i] = dp[i - 1] + dp[i - 2] * (n - 1)
    return dp[m]
