def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        term = ''
        if coeff < 0:
            term += '-'
        elif i > 0:
            term += '+'
        if abs(coeff) != 1 or i == 0:
            term += str(abs(coeff))
        if i > 1:
            term += 'x^' + str(i)
        elif i == 1:
            term += 'x'
        terms.append(term)
    return ''.join(terms)
