def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 1:
        return 1
    if n not in memo:
        memo[n] = 0
    for i in range(1, int(n/2) + 1):
        if n % i == 0 and i <= last:
            memo[n] += count_sequences(n // i, i, memo)
    return memo[n]
