def calculate_arrangements(n, m, a):
    # Initialize the dp array with 0s
    dp = [0] * (m + 1)
    dp[0] = 1

    # Loop through each type of flower
    for i in range(n):
        # Loop through each number of pots
        for j in range(m, -1, -1):
            # Check if the current type of flower can be placed in the current pot
            if j >= a[i]:
                # Add the number of arrangements for the current type of flower
                dp[j] += dp[j - a[i]]

    # Return the number of arrangements modulo (10^6 + 7)
    return dp[m] % (10**6 + 7)
